 function badge(){const box=$('agentAttachment');box.replaceChildren();const thread=current(),items=[...(thread?.attachments||[])];if(state.source&&!items.some(a=>a.attachmentId&&a.attachmentId===state.source.attachmentId))items.unshift(state.source);if(items.length){const summary=document.createElement('small');summary.className='agentAttachmentSummary';summary.textContent=items.length+' مرفقات محفوظة · الصور تُستخدم معًا في الموشن';box.append(summary);}const grid=document.createElement('div');grid.className='agentAttachmentGrid';for(const [i,item]of items.entries()){const card=document.createElement('div');card.className='agentReference';const pick=document.createElement('button');pick.type='button';pick.className='agentReferencePick';pick.classList.toggle('selected',item.attachmentId===state.source?.attachmentId);if(item.kind==='image'){const image=new Image();image.alt='مرجع '+(i+1);image.loading='lazy';image.src=item.thumbnail||(item.attachmentId?mediaUrl('assistant',item.attachmentId):mediaUrl('source'));pick.append(image);}else{const icon=document.createElement('span');icon.textContent={video:'▷',audio:'♫',pdf:'PDF'}[item.kind]||'▧';pick.append(icon);}const name=document.createElement('small');name.textContent=item.name||'مرجع '+(i+1);pick.append(name);pick.onclick=()=>{if(pending||state.busy)return;if(item.attachmentId){switching=true;native('agentSelectAttachment',{id:item.attachmentId});}else native('agentPinSource');};card.append(pick);if(item.attachmentId){const remove=document.createElement('button');remove.type='button';remove.className='agentReferenceRemove';remove.textContent='×';remove.setAttribute('aria-label','استبعاد '+item.name+' من المراجع');remove.onclick=()=>{if(pending||state.busy)return;thread.attachments=thread.attachments.filter(a=>a.attachmentId!==item.attachmentId);if(thread.attachment?.attachmentId===item.attachmentId)thread.attachment=thread.attachments.at(-1)||null;if(state.source?.attachmentId===item.attachmentId){native('agentDetach');state.source=null;selected=null;}save(true);badge();};card.append(remove);}grid.append(card);}box.append(grid);for(const asset of assets){const chip=document.createElement('span');chip.className='agentAttachmentChip';chip.textContent=asset.kind==='music'?'♫ موسيقى للمونتاج':'▧ صورة للمونتاج';box.append(chip);}}
 function busy(value){pending=value;$('agentSend').disabled=switching;$('agentInstall').disabled=value;$('agentStop').hidden=!value&&!state.busy;input.disabled=false;}
 function task(text,percent=null){
  if(!text||job?.tool!=='motionStudio'){clearInterval(motionClock);motionClock=null;}
  const box=$('agentTask');lastTaskText=text;box.replaceChildren();box.hidden=!text;
  let bubble=$('agentWorkBubble');if(!bubble){bubble=document.createElement('button');bubble.id='agentWorkBubble';bubble.type='button';bubble.onclick=()=>{panel.hidden=false;bubble.hidden=true;};document.body.append(bubble);}bubble.hidden=!text||!panel.hidden;bubble.textContent=text?'✧ '+text+' · العودة للمحادثة':'';
  if(!text)return;const status=document.createElement('small');status.textContent=job?'مدار يعمل على ملفك · يستمر في الخلفية':'مدار يفهم طلبك';const title=document.createElement('b');title.textContent=text;box.append(status,title);
  const bar=document.createElement('progress');bar.max=100;box.append(bar);
  if(job?.tool==='motionStudio'){const label=document.createElement('span');label.className='taskEta';label.dataset.motionElapsed='true';box.append(label);const tick=()=>{if(job?.tool!=='motionStudio'){clearInterval(motionClock);motionClock=null;return;}const target=box.querySelector('[data-motion-elapsed]');if(!target)return;const elapsed=Math.max(0,Math.floor((Date.now()-(current()?.task?.started||Date.now()))/1000));target.textContent='الوقت المنقضي: '+Math.floor(elapsed/60)+':'+String(elapsed%60).padStart(2,'0');};tick();if(!motionClock)motionClock=setInterval(tick,1000);progressSample=null;}else if(Number.isFinite(percent)&&percent>=0){percent=Math.min(100,percent);bar.value=percent;const label=document.createElement('span');label.className='taskEta';label.textContent=percent+'٪';const now=Date.now();if(!progressSample||percent<progressSample.percent||text!==progressSample.stage){progressSample={percent,time:now,stage:text};}else if(percent-progressSample.percent>=3&&now-progressSample.time>=4000){const left=(100-percent)*(now-progressSample.time)/(percent-progressSample.percent)/1000;if(left>0&&left<86400)label.textContent+=' · متبقٍ نحو '+(left>=60?Math.ceil(left/60)+' دقيقة':Math.ceil(left)+' ثانية');}box.append(label);}
 }
