 function isMotionRevision(text){const thread=current(),last=(thread?.messages||[]).filter(m=>m.result).at(-1);if(MadarConversation.motionFeedback(text,{project:thread?.motionProject,relevant:!last||!!last.motionProject}))return true;text=text.normalize('NFKC').replace(/[\u064b-\u065f\u0670]/g,'');if(!current()?.motionProject||/(?:موشن|إعلان|اعلان|فيديو|مشروع)\s+جديد/.test(text))return false;if(/^(?:(?:كمل|أكمل|اكمل|تابع)[ ،]*)?(?:بدون|تجاهل|اترك)\s+الرابط/.test(text)&&/تعذرت قراءة الصفحة|أرسل رابط صفحة عامة/.test(current().messages.filter(m=>m.role==='assistant').at(-1)?.text||''))return true;if(/الصورة|للصورة|ملف PDF|التسجيل/.test(text)&&!/المشهد|الموشن|الإعلان|الاعلان|الفيديو السابق/.test(text))return false;return /^(?:طيب[ ،]*)?(?:عدل|عدّل|غير|غيّر|خلي|خلّ|أضف|اضف|بدل|بدّل|قلل|قصّر|طوّل|احذف المشهد)/.test(text)&&/مشهد|الإعلان|الاعلان|الموشن|النهاية|النهايه|البداية|العنوان|التعليق|الخلفية|الألوان|الالوان|الخط|النص|العبارة|العباره|الجملة|الجمله|الكلمة|الكلمه|المكتوب|الكتابة/.test(text)||/^(?:أعد|اعد|سوي|سو)\s+(?:لي\s+)?(?:نفس\s+)?(?:الموشن|الإعلان|الاعلان|الفيديو السابق)/.test(text);}
 // «اضف هذه الصور بدل التكرار» after a finished advert: a visual revision of that advert, decided
 // locally (it must not depend on the online planner). Returns 'photos', 'logo' or ''.
 function motionImageRevision(text){
  const thread=current();if(!thread?.motionProject)return '';const last=(thread.messages||[]).filter(m=>m.result).at(-1);if(last&&!last.motionProject)return '';
  const t=MadarConversation.normalize(text);if(/(?:موشن|اعلان|فيديو|مشروع)\s+جديد|\b(?:pdf|qr)\b|ترجم|استخرج|اعزل|الخلفيه/i.test(t))return '';
  const verb=/(?:^|\s)(?:و)?(?:اضف|ضيف|ضف|حط|استخدم|استعمل|بدل|استبدل|غير|ركب|دخل|خل|خلي)(?:\s|$)/.test(t),pictures=/(?:^|\s)(?:هذه|هذي|هاذي|ال)?(?:صور|صوره|الصور|الصوره|لقطات|اللقطات|شعار|الشعار|لوقو|لوجو)(?=\s|$|[.،,!؟])/.test(t);
  // «خل الشعار في الأخير» or «كبر الصورة» change the layout, not the pictures: that is a normal revision.
  // Image-tool requests («غير حجم الصورة», «حولها png») stay with the tools; one picture needs the advert named.
  if(/حجم|ابعاد|بكسل|ارتفاع|العرض|ضغط|صيغه|png|jpe?g|webp|تدوير|قص(?:\s|$)|دقه/.test(t))return '';
  if(!/(?:^|\s)(?:ال)?(?:صور|لقطات)(?=\s|$|[.،,!؟])|شعار|لوقو|لوجو/.test(t)&&!/الاعلان|للاعلان|بالاعلان|الموشن|الفيديو/.test(t))return '';
  if(!verb||!pictures||/(?:^|\s)(?:اول|بالاول|الاول|اخر|الاخير|بالاخير|النهايه|بالنهايه|البدايه|بالبدايه|اكبر|اصغر|كبر|صغر|مكان|يمين|يسار|فوق|تحت|لون|الوان)(?=\s|$|[.،,!؟])/.test(t))return '';return /شعار|لوقو|لوجو/.test(t)&&!/صور/.test(t)?'logo':'photos';
 }
