 function validateActions(actions){if(!Array.isArray(actions)||actions.length>8)throw Error('عدد خطوات المونتاج غير صالح');let duration=state.tool==='editor'?editDuration():state.source.duration/1000,silence=false,layerCount=state.tool==='editor'?(state.layers||[]).length:0;let ranges=state.tool==='editor'?state.segments.map(r=>[...r]):[[0,duration]];for(let i=0;i<actions.length;i++){const action=actions[i];if(!['trim','remove','addText','addImage','addMusic','silence','transcribe','smartEdit','stutters','captions','enhance','export'].includes(action.action))throw Error('خطوة مونتاج غير مدعومة');if(silence&&['trim','remove','addText','addImage','addMusic'].includes(action.action))throw Error('اجعل القص اليدوي والعناصر قبل قص السكتات');if(action.action==='silence'){if(silence)throw Error('قص السكتات مرة واحدة في الطلب');silence=true;}if(action.action==='export'&&i!==actions.length-1)throw Error('التصدير يكون آخر خطوة');if(['trim','remove','addText','addImage','addMusic'].includes(action.action)){if(!Number.isFinite(action.start)||!Number.isFinite(action.end)||action.start<0||action.end<=action.start||action.end>duration+.001)throw Error('حدد بداية ونهاية داخل مدة الفيديو الحالية');if(['trim','remove'].includes(action.action)){const next=[];let at=0;for(const r of ranges){const len=r[1]-r[0],keep=action.action==='trim'?[[Math.max(at,action.start),Math.min(at+len,action.end)]]:[[at,Math.min(at+len,action.start)],[Math.max(at,action.end),at+len]];for(const [a,b]of keep)if(b-a>=.05)next.push([r[0]+a-at,r[0]+b-at]);at+=len;}if(!next.length||next.length>50)throw Error('القص تجاوز حدود أجزاء المشروع');ranges=next;}if(action.action==='trim')duration=action.end-action.start;if(action.action==='remove'){duration-=action.end-action.start;if(duration<.05)throw Error('لا يمكن حذف المقطع كاملًا');}}if(['addText','addImage'].includes(action.action)&&++layerCount>20)throw Error('الحد 20 عنصرًا في الفيديو');if(action.action==='addText'&&(!action.text?.trim()||action.text.length>1000))throw Error('اكتب النص الذي تريد إضافته');if(action.action==='addImage'&&!assets.some(a=>a.kind==='image'))throw Error('أرفق صورة للمونتاج من زر الإرفاق');if(action.action==='addMusic'&&!assets.some(a=>a.kind==='music'))throw Error('أرفق الموسيقى من زر الإرفاق');if(action.volume!==undefined&&(!Number.isFinite(action.volume)||action.volume<0||action.volume>200))throw Error('مستوى الصوت خارج الحدود');}}
