 async function executeActions(actions,throwOnFailure=false){validateActions(actions);if(state.tool!=='editor'||!$('editTimeline'))openTool('editor');else $('sheet').hidden=false;editSave();busy(true);state.montageRunning=true;try{for(const a of actions){switch(a.action){case'trim':keepComposition(a.start,a.end,false);break;case'remove':keepComposition(a.start,a.end,true);break;case'addText':addLayer({type:'text',text:a.text,start:a.start,end:a.end});break;case'addImage':{const image=assets.filter(x=>x.kind==='image').at(-1);addLayer({type:'image',name:image.name,thumbnail:image.thumbnail,start:a.start,end:a.end});break;}case'addMusic':{const music=assets.filter(x=>x.kind==='music').at(-1);setEditorBed(music);state.bed.start=a.start;state.bed.end=a.end;state.bed.gain=a.volume??25;$('bedStart').value=a.start;$('bedEnd').value=a.end;$('bedGain').value=state.bed.gain;break;}case'enhance':$('normalize').value='peak';break;case'silence':job={thread:active,tool:'editor'};await window.runMontageAction('silence');break;case'transcribe':case'smartEdit':case'stutters':case'captions':job={thread:active,tool:'editor'};await window.runMontageAction(a.action);break;case'export':startExport();break;}}$('editLayers').replaceChildren();layerForm();drawSegments();if(!state.busy){line('طبّقت تعديلات المونتاج. تقدر تعاينها أو تطلب «تصدير».');const view=document.createElement('button');view.className='agentToolButton';view.textContent='فتح المونتاج للمعاينة';view.onclick=()=>panel.hidden=true;log.lastChild?.append(view);}}catch(e){line(e.message||'توقفت خطوات المونتاج');clearJob();task('');queued=[];if(throwOnFailure)throw e;}finally{state.montageRunning=false;busy(false);if(!state.busy){clearJob();if(!throwOnFailure)nextQueued();}}}
